# Edit this file, then run: Rscript scripts/build_boba_app.R
# Base R graphics keeps browser downloads small. All amounts are AUD.
library(shiny)
blue <- "#4682B4"
coral <- "#F08080"
red <- "#B22222"
ui <- fluidPage(
  tags$head(tags$script(HTML('document.addEventListener("shiny:connected", () => window.parent.postMessage({bobaReady:true},location.origin)); window.addEventListener("message", function(event) { if(event.origin === window.location.origin && ["sample", "sampling", "ci"].includes(event.data?.bobaTab)) { Shiny.setInputValue("requestedTab", event.data.bobaTab, {priority:"event"}); } });')), tags$style(HTML('
    body {font-family: "Fira Sans", sans-serif; color:#171717; background:white; font-size:16px;}
    .container-fluid {padding:8px 18px;} .controls {display:flex; gap:24px; align-items:center;}
    .controls > div {flex:1;} .form-group {margin-bottom:6px;} .btn-primary {background:#006DAE; border-color:#006DAE;}
    .nav-tabs>li.active>a {color:#006DAE; font-weight:bold;} .nav-tabs>li>a {color:#444;}
    .cards {display:flex; gap:18px; margin:12px 0;} .stat {flex:1; background:#f4f7fa; padding:10px 16px; border-left:4px solid #4682B4;}
    .stat strong {display:block; font-size:27px;} .note {color:#555; font-size:14px; margin:6px 0;}
  '))),
  div(class="controls",
    sliderInput("n", "Cups per sample (n)", min=5, max=200, value=30, step=1),
    sliderInput("mu", "Population mean (AUD)", min=6, max=10, value=8, step=.1),
    sliderInput("sigma", "Population SD (AUD)", min=.3, max=1.5, value=1.2, step=.1)),
  div(style="display:flex;gap:14px;align-items:center;",
    numericInput("reps", "Number of samples to draw", value=1, min=1, max=1000, step=1, width="240px"),
    actionButton("draw", "Simulate prices", class="btn-primary"),
    actionButton("reset", "Reset")),
  div(class="note", "Illustrative Australian prices: Normal population with mean $8 and SD $1.20 by default. These are teaching assumptions, not national estimates. Changing population settings or n clears the history."),
  tabsetPanel(id="view", selected="sample",
    tabPanel("1. A sample", value="sample", uiOutput("cards"), plotOutput("samplePlot", height="240px"),
      div(class="note", "Bars: latest sample prices. Blue curve: fitted Normal density using the sample mean and SD.")),
    tabPanel("2. Sampling distribution", value="sampling", uiOutput("historySummary"), plotOutput("samplingPlot", height="280px"),
      div(class="note", "Bars: one mean per simulated sample. Coral curve: theoretical Normal sampling distribution, centred at μ with SD = σ / √n.")),
    tabPanel("3. A confidence interval", value="ci", uiOutput("ciSummary"), plotOutput("ciPlot", height="280px"),
      div(class="note", "95% t interval: sample mean ± t(0.975, n − 1) × s / √n. Across repeated samples, about 95% of these intervals contain μ.")))
)
server <- function(input, output, session) {
  observeEvent(input$requestedTab, updateTabsetPanel(session, "view", selected=input$requestedTab))
  # Keep all sample means, but only the latest raw sample, for efficient reuse.
  history <- reactiveVal(numeric())
  latest <- reactiveVal(NULL)
  observeEvent(list(input$n, input$mu, input$sigma, input$reset), {
    history(numeric()); latest(NULL)
  }, priority=10)
  observeEvent(input$draw, {
    req(is.finite(input$reps), input$reps >= 1)
    reps <- min(1000L, as.integer(input$reps))
    draws <- matrix(rnorm(input$n * reps, input$mu, input$sigma), nrow=input$n)
    history(c(history(), colMeans(draws)))
    latest(draws[, reps])
  })
  sampleStats <- reactive({
    req(latest())
    x <- latest(); se <- sd(x)/sqrt(length(x))
    list(mean=mean(x), sd=sd(x), se=se, ci=mean(x)+c(-1,1)*qt(.975,length(x)-1)*se)
  })
  money <- function(x) sprintf("$%.2f", x)
  output$cards <- renderUI({
    if (is.null(latest())) return(p("Choose your settings, then click Simulate prices."))
    s <- sampleStats()
    div(class="cards",
      div(class="stat", "Sample mean (x̄)", strong(money(s$mean))),
      div(class="stat", "Sample SD (s)", strong(money(s$sd))),
      div(class="stat", "Estimated SE (s / √n)", strong(money(s$se))))
  })
  plotStyle <- function() par(mar=c(4.2,4.2,1.2,1), mgp=c(2.6,.7,0), cex=1.25, fg="#737373", col.axis="#171717", col.lab="#171717", family="sans")
  output$samplePlot <- renderPlot({
    validate(need(!is.null(latest()), "Draw a sample to see its prices."))
    plotStyle(); x <- latest(); s <- sampleStats()
    hist(x, probability=TRUE, breaks="FD", col=adjustcolor(blue,.65), border="white", main="", xlab="Boba price (AUD)", ylab="Density",
      xlim=range(c(x,input$mu+c(-4,4)*input$sigma)))
    curve(dnorm(x,s$mean,s$sd), add=TRUE, col=blue, lwd=3)
  }, res=110)
  output$historySummary <- renderUI({
    h <- history()
    p(strong(paste(length(h), "simulated samples")), sprintf(" | Population mean: %s | Theoretical SE: $%.3f",money(input$mu),input$sigma/sqrt(input$n)))
  })
  output$samplingPlot <- renderPlot({
    plotStyle(); h <- history(); se <- input$sigma/sqrt(input$n)
    limits <- range(c(input$mu+c(-4,4)*se,h))
    grid <- seq(limits[1],limits[2],length.out=500)
    if(length(h)>1) {
      bins <- hist(h, breaks="FD", plot=FALSE)
      plot(bins, freq=FALSE, col=adjustcolor(blue,.65), border="white", main="", xlab="Sample mean price (AUD)", ylab="Density", xlim=limits, ylim=c(0,max(bins$density,dnorm(grid,input$mu,se))))
      lines(grid,dnorm(grid,input$mu,se),col=coral,lwd=3)
    } else {
      plot(grid,dnorm(grid,input$mu,se),type="l",col=coral,lwd=3,xlab="Sample mean price (AUD)",ylab="Density")
      if(length(h)) rug(h,col=blue,lwd=3)
    }
    abline(v=input$mu,lty=2,col="#737373")
    legend("topright",c("Simulated means","Theoretical distribution"),fill=c(blue,NA),border=NA,lty=c(NA,1),col=c(blue,coral),bty="n",cex=.85)
  }, res=110)
  output$ciSummary <- renderUI({
    if(is.null(latest())) return(p("Draw a sample to estimate the population mean."))
    s <- sampleStats(); captured <- s$ci[1]<=input$mu && s$ci[2]>=input$mu
    p(sprintf("Latest sample (#%s): 95%% CI [%s, %s]. ",length(history()),money(s$ci[1]),money(s$ci[2])),
      strong(style=paste0("color:",if(captured) blue else red),if(captured) "Contains the population mean." else "Misses the population mean."))
  })
  output$ciPlot <- renderPlot({
    validate(need(!is.null(latest()), "Draw a sample to see its confidence interval."))
    plotStyle(); s <- sampleStats(); x <- latest(); captured <- s$ci[1]<=input$mu && s$ci[2]>=input$mu
    colour <- if(captured) blue else red
    plot(NA,xlim=range(c(x,s$ci,input$mu+c(-3,3)*input$sigma)),ylim=c(0,2),yaxt="n",ylab="",xlab="Boba price / mean price (AUD)",bty="n")
    abline(v=input$mu,lty=2,col=coral,lwd=3)
    points(x,rep(.45,length(x)),pch=16,col=adjustcolor(blue,.4))
    segments(s$ci[1],1.2,s$ci[2],1.2,col=colour,lwd=5)
    segments(s$ci,c(1.1,1.1),s$ci,c(1.3,1.3),col=colour,lwd=2)
    points(s$mean,1.2,pch=19,col=colour,cex=1.5)
    text(s$mean,1.55,paste("Sample mean",money(s$mean)),col=colour)
    text(input$mu,1.9,paste("Population mean",money(input$mu)),col="#171717")
    mtext("Individual cups",side=2,at=.45,las=1,cex=.7)
  },res=110)
}
shinyApp(ui, server)
